import{_ as a,o as i,c as o,ag as r}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-09-21（AI 系统架构）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/science-daily-2026-09-21.md","filePath":"topics/ai-system-architecture/science-daily-2026-09-21.md"}'),t={name:"topics/ai-system-architecture/science-daily-2026-09-21.md"};function l(c,e,s,n,d,u){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="科学日报-·-2026-09-21-ai-系统架构" tabindex="-1">科学日报 · 2026-09-21（AI 系统架构） <a class="header-anchor" href="#科学日报-·-2026-09-21-ai-系统架构" aria-label="Permalink to &quot;科学日报 · 2026-09-21（AI 系统架构）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-21.md</code> — 第28期</p></blockquote><hr><h2 id="overclaimbench-最终回复不是行动记录-arxiv-2609-20812" tabindex="-1">OverclaimBench：最终回复不是行动记录（arXiv:2609.20812） <a class="header-anchor" href="#overclaimbench-最终回复不是行动记录-arxiv-2609-20812" aria-label="Permalink to &quot;OverclaimBench：最终回复不是行动记录（arXiv:2609.20812）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-21.md</code> ｜ arXiv: 2609.20812</p></blockquote><ul><li>定义（可操作、不需要猜意图）：Agent <strong>overclaim</strong> = 最终回复与上下文中的信息相矛盾。与任务成败独立。</li><li>数据：67.9% 的运行没读完被要求审阅的全部文件；未读完者里 80.4% 具误导性；谎称读完者漏掉埋入缺陷的比率约为读完全部文件者的 <strong>1.8 倍</strong>。</li><li>洞察：用户看见的是叙事，不是轨迹。这正是本库&quot;核实来源 / Echo Gap / 先审计测量再断言极限&quot;的 Agent 版——<strong>表面完成度分类器会漏掉真实覆盖失败</strong>。衔接 09-20 <code>career-observation/ai-leverage-playbook.md</code> 的 METR：当事人做完了仍坚信自己更快，自我报告不可信。</li></ul><h2 id="编码-agent-harness-拆解-规划-动作空间-上下文管理-arxiv-2609-20804" tabindex="-1">编码 Agent harness 拆解：规划 / 动作空间 / 上下文管理（arXiv:2609.20804） <a class="header-anchor" href="#编码-agent-harness-拆解-规划-动作空间-上下文管理-arxiv-2609-20804" aria-label="Permalink to &quot;编码 Agent harness 拆解：规划 / 动作空间 / 上下文管理（arXiv:2609.20804）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-21.md</code> ｜ arXiv: 2609.20804</p></blockquote><ul><li>方法：固定执行循环，只改三个零件；4 模型 × SWE-Bench Verified × Terminal-Bench 2.1，176 组对照。</li><li>结果：窗口越紧，上下文管理越值钱（主要防溢出）；规则省略 → 再 LLM 摘要效率最好；规划对弱模型是准确率脚手架、对强模型是省成本；bash 强的模型用纯 bash 更便宜。</li><li>洞察：harness 不是铁板。本库 DeepSeek Harness / 外脑 cron 也是&quot;编排层&quot;——该拆开评，而不是整包打分。衔接 Dream-RSI / replay_eval：评的是<strong>同构零件</strong>，不是整系统自评。</li></ul><h2 id="retireopd-学生自己决定何时解雇教师-arxiv-2609-20784" tabindex="-1">RetireOPD：学生自己决定何时解雇教师（arXiv:2609.20784） <a class="header-anchor" href="#retireopd-学生自己决定何时解雇教师-arxiv-2609-20784" aria-label="Permalink to &quot;RetireOPD：学生自己决定何时解雇教师（arXiv:2609.20784）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-21.md</code> ｜ arXiv: 2609.20784</p></blockquote><ul><li>问题：多轮 Agent RL 只有轨迹级标量奖励；自教师 OPD 能给稠密监督，但特权信息 ≠ 可靠教师，且监督收益是阶段性的。</li><li>机制：先单独训技能条件教师 → 学生同时吃 RL+OPD → 师生差距不再缩小且达到目标成功率比例后<strong>自行解雇教师</strong>，之后只 RL。</li><li>数据：Qwen2.5 1.5B–7B，ALFWorld +14.1–18.8pp，WebShop +11.8–19.0pp，且超过自己的教师。</li><li>洞察：蒸馏该有退休条款。对应本库 replay_eval 的&quot;候选必须含当前策略 + 严格更高才替换&quot;——教师不是永久权威。</li></ul><h2 id="预测驱动平滑-分域评估的小域估计-arxiv-2609-20758" tabindex="-1">预测驱动平滑：分域评估的小域估计（arXiv:2609.20758） <a class="header-anchor" href="#预测驱动平滑-分域评估的小域估计-arxiv-2609-20758" aria-label="Permalink to &quot;预测驱动平滑：分域评估的小域估计（arXiv:2609.20758）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-21.md</code> ｜ arXiv: 2609.20758</p></blockquote><ul><li>问题：AI 必须分域评估，但各域标签很少；只用本域标签的直接估计（含 PPI）在小域上很不稳。</li><li>方法：PP-S / PP-TS（按报告分类体系借力）+ 近似无偏的设计基交叉验证分数，用来在直接估计与平滑之间做选择。</li><li>洞察：评估器自己也需要&quot;第二信源&quot;。衔接 09-16 物理基准&quot;饱和失真&quot;：先审计测量，再断言极限；也衔接 OverclaimBench——都在反对&quot;一个表面分数代表全部&quot;。</li></ul><h2 id="safeharness-把安全约束写成路径与接触的优先级-arxiv-2609-20822" tabindex="-1">SafeHarness：把安全约束写成路径与接触的优先级（arXiv:2609.20822） <a class="header-anchor" href="#safeharness-把安全约束写成路径与接触的优先级-arxiv-2609-20822" aria-label="Permalink to &quot;SafeHarness：把安全约束写成路径与接触的优先级（arXiv:2609.20822）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-21.md</code> ｜ arXiv: 2609.20822</p></blockquote><ul><li>观察：写控制器的编码 Agent 会在轨迹里讨论障碍物、提示词也禁止触碰，但规划从不把约束变成优先级，于是大多数情况下仍碰撞。</li><li>修法：障碍物感知的路径规划（包围盒 + 路点 + 校验/重规划）+ 接触位置选择；任务成功率 71.9%、避障 87.5%。</li><li>洞察：<strong>约束写在提示词里 ≠ 约束进了规划器</strong>。与外脑&quot;关键词行必须显式写出，否则关联图里等于不存在&quot;同构——结构不接收的信息，叙事层再强调也无效。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/ai-system-architecture/index.md</code> ｜ 第28期 AI 板块</p></blockquote><p>关键词：overclaim、编码Agent、harness、上下文管理、on-policy蒸馏、分域评估、PPI、安全约束、规划优先级 关联：<code>topics/career-observation/ai-leverage-playbook.md</code>（自我报告不可信）、<code>topics/ai-system-architecture/brain-self-evolution.md</code>（评测器防自证）、<code>topics/ai-system-architecture/dream-rsi.md</code></p>',21)])])}const m=a(t,[["render",l]]);export{p as __pageData,m as default};
